create table if not exists public.yuni_goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,category text,goal_type text default 'monthly',target_value numeric,current_value numeric default 0,start_date date,due_date date,status text default '진행중',description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.yuni_projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,category text,progress integer default 0 check(progress between 0 and 100),status text default '진행중',start_date date,due_date date,description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.yuni_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,goal_id uuid references public.yuni_goals(id) on delete set null,project_id uuid references public.yuni_projects(id) on delete set null,title text not null,task_date date default current_date,priority text default '보통',status text default '미완료',completed_at timestamptz,memo text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.yuni_habits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,frequency text default 'daily',is_active boolean default true,created_at timestamptz default now());
create table if not exists public.yuni_habit_logs(id uuid primary key default gen_random_uuid(),habit_id uuid not null references public.yuni_habits(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,log_date date default current_date,completed boolean default true,note text,unique(habit_id,log_date));
create table if not exists public.yuni_gratitude(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entry_date date default current_date,gratitude_1 text,gratitude_2 text,gratitude_3 text,reflection text,created_at timestamptz default now(),unique(user_id,entry_date));
create table if not exists public.yuni_budget_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,entry_date date default current_date,entry_type text not null,category text,description text,amount numeric(14,0) not null default 0,payment_method text,created_at timestamptz default now());
create table if not exists public.yuni_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,note_type text default 'memo',title text not null,content text,tags text[],source_url text,is_favorite boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.daily_briefings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,briefing_date date default current_date,morning_summary text,evening_summary text,top_priorities jsonb default '[]'::jsonb,achievements jsonb default '[]'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id,briefing_date));
do $$ declare t text; begin foreach t in array array['yuni_goals','yuni_projects','yuni_tasks','yuni_habits','yuni_habit_logs','yuni_gratitude','yuni_budget_entries','yuni_notes','daily_briefings'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists owner_all on public.%I',t); execute format('create policy owner_all on public.%I for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid())',t); end loop; end $$;
notify pgrst, 'reload schema';
select 'YE PLATFORM 유니 영역 설치 완료' as result;